MAX_PAYLOAD = 16 * 1024 * 1024
MAX_FILE = 2 * 1024 * 1024


def sha256(data):
    return hashlib.sha256(data).hexdigest()


def decode_repository():
    packed = base64.b64decode(PAYLOAD_B64, validate=True)
    if sha256(packed) != PAYLOAD_SHA256:
        raise ValueError('Hash i payload-it nuk përputhet.')
    inflater = zlib.decompressobj()
    raw = inflater.decompress(packed, MAX_PAYLOAD + 1)
    if len(raw) > MAX_PAYLOAD or inflater.unconsumed_tail or not inflater.eof:
        raise ValueError('Payload tejkalon limitin ose është i paplotë.')
    if inflater.unused_data:
        raise ValueError('Të dhëna të tepërta pas payload-it.')
    manifest = json.loads(raw)
    if manifest.get('version') != 1 or not isinstance(manifest.get('files'), dict):
        raise ValueError('Manifest i pavlefshëm.')
    if not 1 <= len(manifest['files']) <= 500:
        raise ValueError('Numër i pavlefshëm skedarësh.')
    decoded, case_names = {}, set()
    for name, item in manifest['files'].items():
        if not isinstance(name, str) or not name or len(name) > 240:
            raise ValueError('Emër i pavlefshëm.')
        path = PurePosixPath(name)
        parts = name.split('/')
        if (path.is_absolute() or any(p in ('', '.', '..') for p in parts)
                or any(c in name for c in ('\\', ':', '\x00'))
                or any(ord(c) < 32 for c in name)
                or any(p.endswith((' ', '.')) for p in parts)):
            raise ValueError('Rrugë e pasigurt: ' + name)
        if name.casefold() in case_names:
            raise ValueError('Emra me konflikt shkronjash.')
        case_names.add(name.casefold())
        if not isinstance(item, dict) or set(item) != {'data', 'sha256'}:
            raise ValueError('Përshkrim skedari i pavlefshëm.')
        data = base64.b64decode(item['data'], validate=True)
        if len(data) > MAX_FILE or sha256(data) != item['sha256']:
            raise ValueError('Hash/limit skedari i pavlefshëm: ' + name)
        decoded[name] = data
    # A file must never also be a directory, including case-insensitive systems.
    folded = {name.casefold() for name in decoded}
    for name in decoded:
        parts = name.split('/')
        if any('/'.join(parts[:i]).casefold() in folded for i in range(1, len(parts))):
            raise ValueError('Konflikt skedar/directory.')
    return decoded


def safe_target(target):
    path = Path(os.path.abspath(os.fspath(target)))
    if path == path.parent:
        raise ValueError('Target nuk mund të jetë root.')
    # lstat detects dangling symlinks; do not resolve them before this check.
    for ancestor in reversed((path.parent,) + tuple(path.parent.parents)):
        info = ancestor.lstat()
        if stat.S_ISLNK(info.st_mode) or not stat.S_ISDIR(info.st_mode):
            raise ValueError('Parent duhet të jetë directory real, pa symlink.')
    if os.path.lexists(path):
        raise FileExistsError('Target ekziston; asnjë overwrite nuk lejohet.')
    return path


def materialize(target='janus-cloud'):
    files = decode_repository()  # Verify everything before creating any target.
    root = safe_target(target)
    root.mkdir(mode=0o700)  # Exclusive creation; fails if target appeared meanwhile.
    try:
        for name, data in sorted(files.items()):
            dest = root.joinpath(*PurePosixPath(name).parts)
            dest.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
            # The private, newly created root contains no symlinks. Still check
            # each descendant and use exclusive/no-follow file creation.
            current = root
            for part in PurePosixPath(name).parts[:-1]:
                current = current / part
                if current.is_symlink() or not current.is_dir():
                    raise ValueError('Directory i pasigurt gjatë shkrimit.')
            flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
            flags |= getattr(os, 'O_NOFOLLOW', 0)
            fd = os.open(dest, flags, 0o600)
            with os.fdopen(fd, 'wb') as stream:
                stream.write(data)
            if dest.is_symlink() or sha256(dest.read_bytes()) != sha256(data):
                raise ValueError('Verifikimi pas shkrimit dështoi.')
    except Exception:
        # Remove only this freshly created private target, never an existing repo.
        if root.is_dir() and not root.is_symlink():
            shutil.rmtree(root)
        raise
    print('Janus cloud u rikrijua: ' + str(root))
    print(str(len(files)) + ' skedarë të verifikuar; pa kredenciale ose deploy.')
    print('Lexo README.md; pastaj npm ci dhe konfigurim privat .env.')
    return root


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('target', nargs='?', default='janus-cloud',
                        help='Directory i ri; default janus-cloud')
    args = parser.parse_args()
    try:
        materialize(args.target)
    except (ValueError, OSError, KeyError, TypeError, zlib.error) as error:
        print('Rikrijimi u refuzua: ' + str(error), file=sys.stderr)
        return 1
    return 0


if __name__ == '__main__':
    sys.exit(main())
